"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[52285],{77776:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SettingsGuiController","desc":"Binds the Studio-authored `StarterGui.SettingsGui` (Ocean Sunset rebuild, see\\n`roblox-gui-prototypes/2026-10-27-settings-gui-prototype.html`) to\\n`SettingsClient`. Opens from a TopbarPlus icon (toggle key K). Each row maps\\nto one setting key; a number setting drives a slider, a boolean setting\\ndrives a toggle. Rows read `SettingsClient.Get`, write `SettingsClient.Set`,\\nand repaint on `Signals.OnSettingChanged` (the join-sync can land after this\\nbinds). Size follows the screen through `MainContainer.UIScale`: wide =\\nmin(W/1920, H/1022); below 0.68 the compact layout (authored at 844x332,\\nscale clamped to [0.75, 1.5]) applies. The Lobby runs the same tree.","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/SettingsGuiController.client.luau"}}')}}]);